<script>
// Utilities
import {
  mapMutations,
  mapState
} from 'vuex'

export default {
  data: () => ({
    logo: './img/logo.png',
    links: [
      {
        to: '/job/about',
        icon: 'mdi-information',
        text: '简介'
      },
      {
        to: '/job/company-analytics',
        icon: 'mdi-google-analytics',
        text: '公司统计分析'
      },
      {
        to: '/job/job-analytics',
        icon: 'mdi-chart-scatterplot-hexbin',
        text: '职位统计分析'
      },
      {
        to: '/job/map-for-job',
        icon: 'mdi-map-marker',
        text: '地图找工作 - 聚合'
      },
      {
        to: '/job/map-for-job-single-2019',
        icon: 'mdi-map-marker',
        text: '地图找工作 - 散点 - 2019'
      },
      {
        to: '/job/map-for-job-single',
        icon: 'mdi-map-marker',
        text: '地图找工作 - 散点 - 所有'
      },
    ],
    responsive: false
  }),
  computed: {
    ...mapState('app', ['image', 'color']),
    inputValue: {
      get () {
        return this.$store.state.app.drawer
      },
      set (val) {
        this.setDrawer(val)
      }
    },
    items () {
      return this.$t('Layout.View.items')
    }
  },
  mounted () {
    this.onResponsiveInverted()
    window.addEventListener('resize', this.onResponsiveInverted)
  },
  beforeDestroy () {
    window.removeEventListener('resize', this.onResponsiveInverted)
  },
  methods: {
    ...mapMutations('app', ['setDrawer', 'toggleDrawer']),
    onResponsiveInverted () {
      if (window.innerWidth < 991) {
        this.responsive = true
      } else {
        this.responsive = false
      }
    }
  }
}
</script>

